#!/usr/bin/env node
/* TSCG Kit — bundle.js
 * Inlines the stylesheets and scripts of a workshop source page into one
 * self-contained HTML file (opens by double-click, no server).
 * Usage: node kit/tools/bundle.js <workshop>/index.src.html [out.html]
 *        (default output: index.html next to the source)
 * No dependency. Author: Echopraxium with the collaboration of Claude AI
 */
"use strict";
const fs = require("fs"), path = require("path");
const src = process.argv[2];
if (!src) { console.error("usage: node bundle.js <index.src.html> [out.html]"); process.exit(2); }
const out = process.argv[3] || path.join(path.dirname(src), "index.html");
const dir = path.dirname(src);
const read = rel => fs.readFileSync(path.join(dir, rel), "utf8");
let html = fs.readFileSync(src, "utf8");
let n = 0;
html = html.replace(/<link rel="stylesheet" href="([^"]+)">/g, (m, href) => { n++; return `<style>\n/* ${href} */\n${read(href)}\n</style>`; });
html = html.replace(/<script src="([^"]+)"><\/script>/g, (m, s) => { n++; return `<script>\n/* ${s} */\n${read(s).replace(/<\/script/gi, "<\\/script")}\n</script>`; });
html = html.replace(/<!-- Source page\.[\s\S]*?-->\n?/, "");
html = html.replace("<head>", `<head>\n<!-- GENERATED by kit/tools/bundle.js from ${path.basename(src)}: edit the sources, then re-bundle. -->`);
fs.writeFileSync(out, html);
console.log(`bundled ${n} file(s) -> ${out}`);
